<?php ob_start();
$activeLock = $activeLock ?? null;
$active = $activeScan ?? null;
if (!$active && !empty($activeLock)) $active = ['id'=>'n/a','profile'=>'n/a','scope_type'=>'locked','scope_value'=>$activeLock['command'] ?? null,'started_at'=>$activeLock['started_at'] ?? null,'pid'=>$activeLock['pid'] ?? null,'status'=>'locked','files_scanned'=>0,'skipped_media'=>0,'skipped_directories'=>0,'findings_count'=>0];
$started = $active['started_at'] ?? $activeLock['started_at'] ?? null;
